using System;using System.IO;using System.Collections.Generic;
// Original feed24/PVF: satiety+30,10s reuse. CN47(list7) and state103(UID,uint satiety).
// Manual feed is connected. Automatic hunger and pet skill-charge runtime remain separate.
class Offline70PetFoodFG99 {
 internal static bool IsRequest(byte[] body,byte[] keys){return body!=null&&body.Length==16&&Offline70RoleProtocol.Xtea(body,keys,false)[2]==7;}
 internal static Offline70EconomyUseRequest Parse(byte[] body,byte[] keys){byte[] b=Offline70RoleProtocol.Xtea(body,keys,false);return new Offline70EconomyUseRequest{Slot=BitConverter.ToUInt16(b,0),List=b[2],InstanceChecksum=BitConverter.ToUInt32(b,3),ItemId=BitConverter.ToUInt32(b,7),Tick=BitConverter.ToUInt32(b,11)};}
 internal static bool Padding(byte[] body,byte[] keys){return Offline70RoleProtocol.Xtea(body,keys,false)[15]==0;}
 internal static Offline70EconomyState Feed(string path,string receipt,Offline70EconomyUseRequest r,long now,out bool duplicate){if(r==null||r.List!=7||!Offline70PetRenameFG98.SupplySlot(r.Slot)||r.ItemId!=24||now<0||now>DateTime.MaxValue.Ticks-TimeSpan.TicksPerSecond*10)throw new InvalidDataException("Creature feed request");return Offline70Economy.Apply(path,receipt,"pet-feed","7:"+r.Slot+":"+r.ItemId+":"+r.InstanceChecksum+":"+r.Tick,delegate(Offline70EconomyState s){Offline70EconomyEntry food=Offline70Economy.Find(s,7,r.Slot),pet=Offline70PetEquipFG97.Equipped(s);if(food==null||food.ItemId!=24||food.Quantity<1||pet==null||pet.CreatureLevel<1)throw new InvalidDataException("Creature feed ownership or worn pet");if(pet.CreatureFeedUtcTicks!=0&&(now<pet.CreatureFeedUtcTicks||now-pet.CreatureFeedUtcTicks<TimeSpan.TicksPerSecond*10))throw new InvalidDataException("Creature feed cooldown");pet.CreatureSatiety=(byte)Math.Min(100,pet.CreatureSatiety+30);pet.CreatureFeedUtcTicks=now;if(food.Quantity==1)s.Inventory.Remove(food);else food.Quantity--;},out duplicate);}
 internal static byte[] State(Offline70EconomyEntry pet,byte[] keys){if(pet==null||!Offline70PetFG96.IsPet(pet.ItemId)||pet.CreatureKey<2||pet.CreatureSatiety>100)throw new InvalidDataException("Creature feed state");byte[] b=new byte[8];BitConverter.GetBytes(pet.CreatureKey).CopyTo(b,0);BitConverter.GetBytes((uint)pet.CreatureSatiety).CopyTo(b,4);return Offline70RoleProtocol.BatchPacketFG(0,103,b,keys,false);}
 internal static void AddOffers(Dictionary<uint,Offline70CashPurchaseFG45.Offer> offers){uint[] ids={105001,105002,105003,105004},counts={100,300,500,1000},costs={280,680,1080,1880};for(int i=0;i<ids.Length;i++)offers.Add(ids[i],new Offline70CashPurchaseFG45.Offer{Commodity=ids[i],Category=3,Item=24,Cost=costs[i],Once=false,Rewards=new uint[][]{new uint[]{24,counts[i]}}});}
}
partial class Offline70BatchServiceFG {
 readonly Dictionary<ushort,string> feedRequestsFG99=new Dictionary<ushort,string>();
 void FeedPetFG99(byte[] body,ushort sequence){Offline70EconomyUseRequest r=Offline70PetFoodFG99.Parse(body,keys);string fingerprint=Convert.ToBase64String(body),prior;if(feedRequestsFG99.TryGetValue(sequence,out prior)){if(prior!=fingerprint){Send("pet-feed-sequence-failed",Offline70EconomyProtocol.UseReply(r,false,keys));return;}Note("CREATURE_FEED_DUPLICATE_IGNORED");return;}bool success=false;try{if(!Offline70PetFoodFG99.Padding(body,keys)||dungeon.Active&&!dungeon.Loaded)throw new InvalidDataException("Creature feed context or padding");Sync();bool duplicate;assets=Offline70PetFoodFG99.Feed(economyPath,session+"-pet-feed-"+sequence+"-"+r.Tick,r,DateTime.UtcNow.Ticks,out duplicate);success=true;Note("CREATURE_FEED_COMMITTED serial="+Offline70PetEquipFG97.Equipped(assets).CreatureKey+" satiety="+Offline70PetEquipFG97.Equipped(assets).CreatureSatiety+" duplicate="+duplicate);}catch(InvalidDataException e){Note("CREATURE_FEED_REJECTED "+e.Message);}feedRequestsFG99.Add(sequence,fingerprint);Send(success?"pet-feed-used47":"pet-feed-failed47",Offline70EconomyProtocol.UseReply(r,success,keys));if(success){Sync();Send("pet-feed-state103",Offline70PetFoodFG99.State(Offline70PetEquipFG97.Equipped(assets),keys));}}
}
